+  font-size: 12px;
+}
+
+/* --- the result dialog ---------------------------------------------------- */
+
+dialog {
+  width: min(520px, 92vw);
+  padding: 24px 28px 20px;
+  color: var(--text);
+  background: var(--surface);
+  border: 1px solid #4a6a80;
+  border-radius: 14px;
+  box-shadow: 0 24px 80px rgb(0 0 0 / 0.6);
+}
+dialog[open] {
